 */
@Component
public class TimeProvider {

    private final Clock clock;

    public TimeProvider() {
        this(Clock.systemUTC());
    }

    public TimeProvider(Clock clock) {
        this.clock = clock;
    }

    /** 当前 UTC 时间。 */
    public Instant now() {
        return Instant.now(clock);
    }
}

